<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Config;use StudPulse\Database\DB;use StudPulse\Security\{Auth,Crypto,RateLimit};use StudPulse\Bars\{BarsOfficialAdapter,ProviderFactory};use StudPulse\Integrations\{Calendar,MpeiSchedule,ScheduleSubgroups};final class CalendarController{public function list(Auth$a):array{$a->browserOnly();return['items'=>DB::all('SELECT id,include_homework,created_at,expires_at,revoked_at FROM calendar_subscriptions WHERE user_id=? ORDER BY created_at DESC',[$a->user['id']])];}public function create(Auth$a,Request$r):array{$a->browserOnly();RateLimit::check('calendar:create:'.$a->user['id'],10,3600);$m=$a->membership;$p=ProviderFactory::make($a);if($p->capabilities()['getMySchedule']['status']!=='supported'){throw new ApiError(503,'BLOCKED_EXTERNAL','Подписка появится после разрешённого подключения расписания');}$group=$p instanceof BarsOfficialAdapter?trim($p->scheduleGroup()):null;if(!$m&&!$group){throw new ApiError(403,'GROUP_UNVERIFIED','Для подписки нужна группа из профиля БАРС.');}$includeHomework=($r->body['includeHomework']??false)===true;if($includeHomework&&!$m){throw new ApiError(403,'GROUP_UNVERIFIED','Для групповых заданий нужно подтверждённое членство.');}$token=Crypto::token();$id=DB::id();DB::run('INSERT INTO calendar_subscriptions(id,user_id,membership_id,ruz_group,token_hash,include_homework,expires_at) VALUES(?,?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 90 DAY))',[$id,$a->user['id'],$m['id']??null,$group?:null,Crypto::hash($token),(int)$includeHomework]);return['id'=>$id,'url'=>rtrim(Config::get('APP_BASE_URL'),'/').'/calendar/feed/'.$id.'/'.$token.'.ics','message'=>'Ссылка действует до 90 дней. Её можно отозвать в настройках.'];}public function revoke(Auth$a,string$id):array{$a->browserOnly();DB::run('UPDATE calendar_subscriptions SET revoked_at=UTC_TIMESTAMP(6) WHERE id=? AND user_id=?',[$id,$a->user['id']]);return['revoked'=>true];}public function feed(string$id,string$token):never{RateLimit::check('calendar:'.$id,30);$row=DB::one('SELECT * FROM calendar_subscriptions WHERE id=? AND token_hash=? AND revoked_at IS NULL AND expires_at>UTC_TIMESTAMP(6)',[$id,Crypto::hash($token)]);if(!$row){throw new ApiError(410,'FEED_EXPIRED','Подписка отозвана или истекла');}$a=Auth::forCalendarFeed($row['user_id'],$row['membership_id']);$tz=new \DateTimeZone('Europe/Moscow');$from=(new \DateTimeImmutable('today',$tz))->modify('-7 days')->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s');$to=(new \DateTimeImmutable('today',$tz))->modify('+85 days')->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s');$p=ProviderFactory::make($a);if(!empty($row['ruz_group'])){$current=$p instanceof BarsOfficialAdapter?trim($p->scheduleGroup()):'';if(!$p instanceof BarsOfficialAdapter||($current!==''&&$current!==$row['ruz_group'])){throw new ApiError(410,'FEED_EXPIRED','Учебная группа изменилась. Создайте новую подписку.');}$schedule=MpeiSchedule::forGroup($row['ruz_group'],$from,$to);$items=ScheduleSubgroups::forUser($schedule,$row['user_id'])->items;}elseif($a->membership){$items=$p->getMySchedule($from,$to)->items;}else{throw new ApiError(410,'FEED_EXPIRED','Подписка недоступна.');}$homework=$row['include_homework']&&$a->membership?DB::all('SELECT * FROM homework WHERE group_id=? AND term_id=? AND deleted_at IS NULL AND due_at>=? AND due_at<?',[$a->membership['group_id'],$a->membership['term_id'],$from,$to]):[];header('Content-Type: text/calendar; charset=utf-8');header('Cache-Control: private, no-store');header('Content-Disposition: inline; filename="studpulse.ics"');echo Calendar::export($items,$homework);exit;}}